// create: myns.FDb.part (Lary)
// global access: part (Lary, by rowid)
// global access: zd_part (Llist)
// global access: ind_part (Thash, hash field part)
// access: myns.Order.p_part (Upptr)
struct FPart { // myns.FPart: inherited from ssimfile
    myns::FPart*       zd_part_next;        // zslist link; -1 means not-in-list
    myns::FPart*       zd_part_prev;        // previous element
    myns::FPart*       ind_part_next;       // hash next
    algo::Smallstr50   part;                //
    i32                amt;                 //   0  amount of part
    algo::Comment      comment;             //
    i32                f_amt;               //   0  f_amount of part. not inherited
    myns::Order*       zd_partorder_head;   // zero-terminated doubly linked list
    i32                zd_partorder_n;      // zero-terminated doubly linked list
    myns::Order*       zd_partorder_tail;   // pointer to last element
    // reftype Llist of myns.FPart.zd_partorder prohibits copy
    // func:myns.FPart..AssignOp
    inline myns::FPart&  operator =(const myns::FPart &rhs) = delete;
    // reftype Llist of myns.FPart.zd_partorder prohibits copy
    // func:myns.FPart..CopyCtor
    inline               FPart(const myns::FPart &rhs) = delete;
private:
    // func:myns.FPart..Ctor
    inline               FPart() __attribute__((nothrow));
    // func:myns.FPart..Dtor
    inline               ~FPart() __attribute__((nothrow));
    friend myns::FPart&         part_Alloc() __attribute__((__warn_unused_result__, nothrow));
    friend myns::FPart*         part_AllocMaybe() __attribute__((__warn_unused_result__, nothrow));
    friend void                 part_RemoveAll() __attribute__((nothrow));
    friend void                 part_RemoveLast() __attribute__((nothrow));
};

